import verified from "./news-sources.verified.json";
import type { Genre, NewsCity } from "@/lib/news/taxonomy";

/**
 * News sources used by the daily refresh and the newspaper directory.
 *
 * ⚠️ This list is GENERATED by `npm run verify:sources`, which fetches every candidate in
 * scripts/news-candidates.json and keeps only URLs that return HTTP 200 and (for feeds) valid
 * RSS/Atom with at least one item. To add a source: add it to the candidates file and re-run.
 */
export interface NewsSource {
  name: string;
  homepage: string;
  feedUrl: string;
  language: "en" | "hi";
  scope: "national" | "regional" | "aggregator";
  city?: NewsCity;
  genre?: Genre;
  active: boolean;
  verifiedAt: string;
}

export type DirectoryGroup = "national-en" | "national-hi" | NewsCity;

export interface DirectoryLink {
  group: DirectoryGroup;
  name: string;
  url: string;
  verifiedAt: string;
}

export const sourcesVerifiedAt: string | null = verified.verifiedAt;
export const newsSources = verified.feeds as NewsSource[];
export const newspaperDirectory = verified.directory as DirectoryLink[];

export function activeSources() {
  return newsSources.filter((s) => s.active);
}
